    assert.match(await list({ search: '"<script>' }), /value="&quot;&lt;script&gt;"/);
    assert.equal(names(await list()).length, 5);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

